import os
import shutil
import csv

def task_func(target_value='332', csv_dir='./csv_files/', processed_dir='./processed_files/', simulate=False):
    """
    Scan csv_dir for CSV files, find the first row index whose first cell equals target_value,
    and optionally move matched files to processed_dir.

    Returns:
        dict: {filename: row_index}
    """
    result = {}

    if not os.path.isdir(csv_dir):
        return result

    try:
        csv_files = sorted(
            name for name in os.listdir(csv_dir)
            if name.lower().endswith('.csv') and os.path.isfile(os.path.join(csv_dir, name))
        )
    except OSError:
        return result

    csv_dir_abs = os.path.abspath(csv_dir)
    processed_dir_abs = os.path.abspath(processed_dir)
    should_move = (not simulate) and (csv_dir_abs != processed_dir_abs)

    if should_move:
        try:
            os.makedirs(processed_dir, exist_ok=True)
        except OSError:
            should_move = False

    for filename in csv_files:
        file_path = os.path.join(csv_dir, filename)
        found_index = None

        try:
            with open(file_path, 'r', newline='', encoding='utf-8-sig') as f:
                reader = csv.reader(f)
                for idx, row in enumerate(reader):
                    if row and str(row[0]) == str(target_value):
                        found_index = idx
                        break
        except (OSError, UnicodeDecodeError, csv.Error):
            continue

        if found_index is not None:
            result[filename] = found_index

            if should_move:
                dest_path = os.path.join(processed_dir, filename)
                try:
                    shutil.move(file_path, dest_path)
                except OSError:
                    pass

    return result
